function verdoppleZahl(zahl) {
  return zahl * 2;
}

console.log(verdoppleZahl(3));
console.log(verdoppleZahl(10));

function addiere(a, b) {
  return a + b;
}

console.log(addiere(4, 5));

function istVolljaehrig(alter) {
  return alter >= 18;
}

console.log(istVolljaehrig(15));
console.log(istVolljaehrig(20));
console.log(istVolljaehrig(18));

function verdopple(x) {
  return x * 2;
}

const verdoppleKurz = (x) => x * 2;

console.log(verdopple(4));
console.log(verdoppleKurz(4));

function summeBis(n) {
  let summe = 0;
  for (let i = 1; i <= n; i++) {
    summe += i;
  }
  return summe;
}

console.log(summeBis(5));

function teile(zaehler, nenner) {
  return zaehler / nenner;
}

console.log(teile(2, 10));
